import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Container,
  Card,
  CardContent,
  Typography,
  Switch,
  FormControlLabel,
  Button,
  AppBar,
  Toolbar,
  IconButton,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  ListItemSecondaryAction,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import {
  ArrowBack,
  DarkMode,
  Notifications,
  VolumeUp,
  Vibration,
  ExitToApp,
  Person,
  ContactPhone,
  History,
  Info,
} from '@mui/icons-material';

import { logout } from '../store/slices/authSlice';
import { toggleTheme } from '../store/slices/themeSlice';
import { updatePreferences } from '../store/slices/userSlice';

const Settings = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const { user } = useSelector((state) => state.auth);
  const { mode } = useSelector((state) => state.theme);
  const { preferences } = useSelector((state) => state.user);

  const [logoutDialog, setLogoutDialog] = useState(false);

  const handlePreferenceChange = (key, value) => {
    dispatch(updatePreferences({ [key]: value }));
  };

  const handleThemeToggle = () => {
    dispatch(toggleTheme());
    handlePreferenceChange('theme', mode === 'light' ? 'dark' : 'light');
  };

  const handleLogout = () => {
    dispatch(logout());
    navigate('/login');
  };

  const settingsItems = [
    {
      icon: <Person />,
      title: 'Profile',
      subtitle: 'Edit your personal information',
      action: () => navigate('/profile'),
      type: 'navigation',
    },
    {
      icon: <ContactPhone />,
      title: 'Emergency Contacts',
      subtitle: 'Manage your emergency contacts',
      action: () => navigate('/emergency-contacts'),
      type: 'navigation',
    },
    {
      icon: <History />,
      title: 'Alert History',
      subtitle: 'View your emergency alerts',
      action: () => navigate('/alert-history'),
      type: 'navigation',
    },
  ];

  const preferenceItems = [
    {
      icon: <DarkMode />,
      title: 'Dark Theme',
      subtitle: 'Switch between light and dark mode',
      value: mode === 'dark',
      onChange: handleThemeToggle,
      type: 'switch',
    },
    {
      icon: <Notifications />,
      title: 'Push Notifications',
      subtitle: 'Receive emergency alerts and updates',
      value: preferences.notifications,
      onChange: (value) => handlePreferenceChange('notifications', value),
      type: 'switch',
    },
    {
      icon: <VolumeUp />,
      title: 'Voice Alerts',
      subtitle: 'Enable voice command detection',
      value: preferences.voiceAlerts,
      onChange: (value) => handlePreferenceChange('voiceAlerts', value),
      type: 'switch',
    },
    {
      icon: <Vibration />,
      title: 'Shake Detection',
      subtitle: 'Trigger alerts by shaking device',
      value: preferences.shakeDetection,
      onChange: (value) => handlePreferenceChange('shakeDetection', value),
      type: 'switch',
    },
  ];

  return (
    <Box>
      {/* Header */}
      <AppBar position="static" elevation={1}>
        <Toolbar>
          <IconButton
            edge="start"
            color="inherit"
            onClick={() => navigate('/dashboard')}
          >
            <ArrowBack />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1, ml: 2 }}>
            Settings
          </Typography>
        </Toolbar>
      </AppBar>

      <Container maxWidth="md" sx={{ py: 3 }}>
        {/* User Info */}
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Account Information
            </Typography>
            <Typography variant="body1" color="text.secondary">
              {user?.fullName}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {user?.email}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {user?.phone}
            </Typography>
          </CardContent>
        </Card>

        {/* Navigation Settings */}
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Account & Data
            </Typography>
            <List disablePadding>
              {settingsItems.map((item, index) => (
                <React.Fragment key={index}>
                  <ListItem button onClick={item.action}>
                    <ListItemIcon>{item.icon}</ListItemIcon>
                    <ListItemText
                      primary={item.title}
                      secondary={item.subtitle}
                    />
                  </ListItem>
                  {index < settingsItems.length - 1 && <Divider />}
                </React.Fragment>
              ))}
            </List>
          </CardContent>
        </Card>

        {/* Preferences */}
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Preferences
            </Typography>
            <List disablePadding>
              {preferenceItems.map((item, index) => (
                <React.Fragment key={index}>
                  <ListItem>
                    <ListItemIcon>{item.icon}</ListItemIcon>
                    <ListItemText
                      primary={item.title}
                      secondary={item.subtitle}
                    />
                    <ListItemSecondaryAction>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={item.value}
                            onChange={(e) => item.onChange(e.target.checked)}
                            color="primary"
                          />
                        }
                        label=""
                      />
                    </ListItemSecondaryAction>
                  </ListItem>
                  {index < preferenceItems.length - 1 && <Divider />}
                </React.Fragment>
              ))}
            </List>
          </CardContent>
        </Card>

        {/* App Information */}
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              About
            </Typography>
            <List disablePadding>
              <ListItem>
                <ListItemIcon>
                  <Info />
                </ListItemIcon>
                <ListItemText
                  primary="App Version"
                  secondary="1.0.0"
                />
              </ListItem>
              <Divider />
              <ListItem>
                <ListItemText
                  primary="NIVRA - AI Powered Women Safety App"
                  secondary="Your personal safety companion with emergency alerts, real-time location sharing, and AI assistance."
                />
              </ListItem>
            </List>
          </CardContent>
        </Card>

        {/* Logout Button */}
        <Card>
          <CardContent>
            <Button
              fullWidth
              variant="outlined"
              color="error"
              startIcon={<ExitToApp />}
              onClick={() => setLogoutDialog(true)}
              sx={{ py: 1.5 }}
            >
              Sign Out
            </Button>
          </CardContent>
        </Card>
      </Container>

      {/* Logout Confirmation Dialog */}
      <Dialog open={logoutDialog} onClose={() => setLogoutDialog(false)}>
        <DialogTitle>Sign Out</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to sign out? You'll need to sign in again to access your account.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setLogoutDialog(false)}>Cancel</Button>
          <Button onClick={handleLogout} color="error" variant="contained">
            Sign Out
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default Settings;
